package br.com.pousada.api;

import br.com.pousada.domain.Room;
import br.com.pousada.repository.RoomRepository;
import io.javalin.http.Context;

import java.util.List;
import java.util.Map;

public class RoomController {
    private final RoomRepository roomRepository;

    public RoomController(RoomRepository roomRepository) {
        this.roomRepository = roomRepository;
    }

    public void getRooms(Context ctx) {
        List<Room> rooms = roomRepository.findAll();
        List<Map<String, Object>> response = rooms.stream()
            .map(room -> Map.of(
                "number", room.getNumber(),
                "type", room.getType().name(),
                "capacity", room.getCapacity(),
                "nightlyRate", room.getNightlyRate()
            ))
            .toList();

        ctx.json(response);
    }
}

